def add_id_token(self, token, token_handler, request):
    if 'state' not in token and request.state:
        token['state'] = request.state

    if request.response_type in ('id_token', 'id_token token'):
        # Generate ID token for OpenID Connect
        id_token = self.create_id_token(token, token_handler, request)
        token['id_token'] = id_token

    return token
